css:
.vs-root{position:absolute;inset:0;font-family:var(--vs-font);overflow:hidden;background:#0b0b0c;}
.vs-panel{position:absolute;top:0;bottom:0;}
.vs-panel-left{left:0;width:58%;background:var(--vs-left);clip-path:polygon(0 0,100% 0,76% 100%,0 100%);}
.vs-panel-right{left:42%;width:58%;background:var(--vs-right);clip-path:polygon(24% 0,100% 0,100% 100%,0 100%);}
.vs-seam{position:absolute;left:50%;top:-10%;width:2px;height:120%;background:var(--vs-accent);transform:translateX(-50%) rotate(13.5deg);}
.vs-round{position:absolute;left:50%;top:52px;transform:translateX(-50%);font-size:var(--vs-round-size);font-weight:700;letter-spacing:6px;color:#c9c9c2;background:rgba(8,8,9,.85);padding:6px 26px;border:1px solid #34343a;text-transform:uppercase;white-space:nowrap;}
.vs-round:empty{display:none;}
.vs-side{position:absolute;top:50%;transform:translateY(-50%);width:500px;display:flex;flex-direction:column;align-items:center;gap:20px;}
.vs-left{left:7%;}
.vs-right{right:7%;}
.vs-avatar{width:var(--vs-avatar-size);height:var(--vs-avatar-size);overflow:hidden;background:#0d0d0e;border:1px solid #3a3a3f;display:flex;align-items:center;justify-content:center;}
.vs-avatar img{width:100%;height:100%;object-fit:cover;display:none;}
.vs-avatar img.is-ready{display:block;}
.vs-fallback{font-size:56px;font-weight:700;color:#55554e;letter-spacing:2px;}
.vs-name{font-size:var(--vs-name-size);font-weight:700;color:#f4f4f0;letter-spacing:.5px;text-align:center;line-height:1.12;max-width:500px;word-break:break-word;}
.vs-badge{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);padding:10px 20px;background:#0b0b0c;border:1px solid var(--vs-accent);}
.vs-vs{font-size:24px;font-weight:700;letter-spacing:5px;color:var(--vs-accent);}
.vs-team{display:flex;align-items:center;gap:10px;max-width:500px;}
.vs-team:not(:has(.vs-team-name:not(:empty),img.is-ready)){display:none;}
.vs-team-logo{position:relative;width:var(--vs-team-logo);height:var(--vs-team-logo);flex:0 0 auto;display:flex;align-items:center;justify-content:center;}
.vs-team-logo img{width:100%;height:100%;object-fit:contain;display:none;}
.vs-team-logo img.is-ready{display:block;}
.vs-team-fallback{width:6px;height:6px;background:var(--vs-accent);}
.vs-team-logo:has(img.is-ready) .vs-team-fallback{display:none;}
.vs-team-name{font-size:var(--vs-team-size);font-weight:700;letter-spacing:2px;line-height:1.2;color:var(--vs-accent);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0;}
.vs-team-name:empty{display:none;}
